def load():
    import openpyxl
    xl_file = 'data/biomedical/input/1-s2.0-S0092867420301070-mmc3.xlsx'
    xls = pd.ExcelFile(xl_file)
    results = []
    for sheet_name in xls.sheet_names:
        try:
            df = pd.read_excel(xl_file, sheet_name=sheet_name)
            results.append({
                'Sheet': sheet_name,
                'Columns': ', '.join(df.columns.tolist()),
                'Shape': f"({df.shape[0]}, {df.shape[1]})",
                'Sample_Data': str(df.head(1).to_dict())
            })
        except Exception as e:
            results.append({
                'Sheet': sheet_name,
                'Columns': f'Error: {str(e)}',
                'Shape': 'N/A',
                'Sample_Data': 'N/A'
            })
    return pd.DataFrame(results)

def process(cbx3_genes) -> pd.DataFrame:
    avg_fdr = cbx3_genes['FDR.phos'].mean()
    return pd.DataFrame({'avg_fdr_cbx3': [avg_fdr]})

def process(other_genes) -> pd.DataFrame:
    avg_fdr = other_genes['FDR.phos'].mean()
    return pd.DataFrame({'avg_fdr_other': [avg_fdr]})

def process(avg_fdr_cbx3, avg_fdr_other) -> pd.DataFrame:
    cbx3_val = avg_fdr_cbx3['avg_fdr_cbx3'].iloc[0]
    other_val = avg_fdr_other['avg_fdr_other'].iloc[0]
    difference = cbx3_val - other_val
    return pd.DataFrame({'difference': [round(difference, 9)]})
